SELECT 'categories' AS table_name, COUNT(*) AS record_count FROM categories
UNION ALL SELECT 'suppliers', COUNT(*) FROM suppliers
UNION ALL SELECT 'warehouses', COUNT(*) FROM warehouses
UNION ALL SELECT 'products', COUNT(*) FROM products
UNION ALL SELECT 'employees', COUNT(*) FROM employees
UNION ALL SELECT 'purchase_orders', COUNT(*) FROM purchase_orders
UNION ALL SELECT 'purchase_order_items', COUNT(*) FROM purchase_order_items
UNION ALL SELECT 'sales', COUNT(*) FROM sales
UNION ALL SELECT 'sale_items', COUNT(*) FROM sale_items
UNION ALL SELECT 'stock_movements', COUNT(*) FROM stock_movements;

SELECT
 (SELECT COUNT(*) FROM categories) +
 (SELECT COUNT(*) FROM suppliers) +
 (SELECT COUNT(*) FROM warehouses) +
 (SELECT COUNT(*) FROM products) +
 (SELECT COUNT(*) FROM employees) +
 (SELECT COUNT(*) FROM purchase_orders) +
 (SELECT COUNT(*) FROM purchase_order_items) +
 (SELECT COUNT(*) FROM sales) +
 (SELECT COUNT(*) FROM sale_items) +
 (SELECT COUNT(*) FROM stock_movements) AS total_records;
 
 USE inventory_management;

-- 1. Display all products
SELECT * FROM products;

-- 2. Display product names and prices
SELECT product_name, unit_price FROM products;

-- 3. Find products above ₹10,000
SELECT * FROM products WHERE unit_price > 10000;

-- 4. Find products with stock below 100
SELECT * FROM products WHERE stock_quantity < 100;

-- 5. Find products between ₹5,000 and ₹20,000
SELECT * FROM products WHERE unit_price BETWEEN 5000 AND 20000;

-- 6. Find products in categories 1, 2, and 3
SELECT * FROM products WHERE category_id IN (1, 2, 3);

-- 7. Find products starting with Product 1
SELECT * FROM products WHERE product_name LIKE 'Product 1%';

-- 8. Sort products by price
SELECT * FROM products ORDER BY unit_price ASC;

-- 9. Display top 10 expensive products
SELECT * FROM products ORDER BY unit_price DESC LIMIT 10;

-- 10. Count total products
SELECT COUNT(*) AS total_products FROM products;

-- 11. Find highest product price
SELECT MAX(unit_price) AS highest_price FROM products;

-- 12. Find average product price
SELECT AVG(unit_price) AS average_price FROM products;

-- 13. Find total stock
SELECT SUM(stock_quantity) AS total_stock FROM products;

-- 14. Count products in each category
SELECT category_id, COUNT(*) AS total_products FROM products GROUP BY category_id;

-- 15. Find categories with more than 40 products
SELECT category_id, COUNT(*) AS total_products FROM products GROUP BY category_id HAVING COUNT(*) > 40;

-- 16. Display products with category names
SELECT p.product_name, c.category_name FROM products p INNER JOIN categories c ON p.category_id = c.category_id;

-- 17. Display products with warehouse names
SELECT p.product_name, w.warehouse_name FROM products p INNER JOIN warehouses w ON p.warehouse_id = w.warehouse_id;

-- 18. Display employees with warehouse names
SELECT e.employee_name, w.warehouse_name FROM employees e INNER JOIN warehouses w ON e.warehouse_id = w.warehouse_id;

-- 19. Display purchase orders with supplier names
SELECT po.purchase_order_id, s.supplier_name, po.order_date FROM purchase_orders po INNER JOIN suppliers s ON po.supplier_id = s.supplier_id;

-- 20. Display sales with employee names
SELECT s.sale_id, e.employee_name, s.total_amount FROM sales s INNER JOIN employees e ON s.employee_id = e.employee_id;

-- 21. Find products above ₹50,000 with category names
SELECT p.product_name, c.category_name, p.unit_price FROM products p INNER JOIN categories c ON p.category_id = c.category_id WHERE p.unit_price > 50000;

-- 22. Find active employees in warehouse 1
SELECT * FROM employees WHERE status = 'Active' AND warehouse_id = 1;

-- 23. Display all categories and products
SELECT c.category_name, p.product_name FROM categories c LEFT JOIN products p ON c.category_id = p.category_id;

-- 24. Find categories without products
SELECT c.category_name FROM categories c LEFT JOIN products p ON c.category_id = p.category_id WHERE p.product_id IS NULL;

-- 25. Display all suppliers and purchase orders
SELECT s.supplier_name, po.purchase_order_id FROM suppliers s LEFT JOIN purchase_orders po ON s.supplier_id = po.supplier_id;

-- 26. Display all products and categories using RIGHT JOIN
SELECT c.category_name, p.product_name FROM categories c RIGHT JOIN products p ON c.category_id = p.category_id;

-- 27. Display product, category, and warehouse details
SELECT p.product_name, c.category_name, w.warehouse_name FROM products p INNER JOIN categories c ON p.category_id = c.category_id INNER JOIN warehouses w ON p.warehouse_id = w.warehouse_id;

-- 28. Display purchase order details
SELECT po.purchase_order_id, s.supplier_name, w.warehouse_name, e.employee_name FROM purchase_orders po INNER JOIN suppliers s ON po.supplier_id = s.supplier_id INNER JOIN warehouses w ON po.warehouse_id = w.warehouse_id INNER JOIN employees e ON po.employee_id = e.employee_id;

-- 29. Display complete sales details
SELECT s.sale_id, s.customer_name, p.product_name, si.quantity FROM sales s INNER JOIN sale_items si ON s.sale_id = si.sale_id INNER JOIN products p ON si.product_id = p.product_id;

-- 30. Find total purchase amount by supplier
SELECT s.supplier_name, SUM(po.total_amount) AS total_purchase FROM suppliers s INNER JOIN purchase_orders po ON s.supplier_id = po.supplier_id GROUP BY s.supplier_name;

-- 31. Find total sales by employee
SELECT e.employee_name, SUM(s.total_amount) AS total_sales FROM employees e INNER JOIN sales s ON e.employee_id = s.employee_id GROUP BY e.employee_name;

-- 32. Find total stock value by category
SELECT c.category_name, SUM(p.stock_quantity * p.unit_price) AS stock_value FROM categories c INNER JOIN products p ON c.category_id = p.category_id GROUP BY c.category_name;

-- 33. Count products in each warehouse
SELECT w.warehouse_name, COUNT(p.product_id) AS total_products FROM warehouses w LEFT JOIN products p ON w.warehouse_id = p.warehouse_id GROUP BY w.warehouse_name;

-- 34. Display stock status
SELECT product_name, stock_quantity, CASE WHEN stock_quantity = 0 THEN 'Out of Stock' WHEN stock_quantity <= reorder_level THEN 'Reorder Required' ELSE 'Available' END AS stock_status FROM products;

-- 35. Find products above average price
SELECT * FROM products WHERE unit_price > (SELECT AVG(unit_price) FROM products);

-- 36. Find the most expensive product
SELECT * FROM products WHERE unit_price = (SELECT MAX(unit_price) FROM products);

-- 37. Find employees working in Chennai
SELECT * FROM employees WHERE warehouse_id IN (SELECT warehouse_id FROM warehouses WHERE location = 'Chennai');

-- 38. Find pending purchase orders
SELECT * FROM purchase_orders WHERE status = 'Pending';

-- 39. Find completed sales
SELECT * FROM sales WHERE status = 'Completed';

-- 40. Find products needing reorder
SELECT * FROM products WHERE stock_quantity <= reorder_level;

-- 41. Update a product price
UPDATE products SET unit_price = 25000 WHERE product_id = 1;

-- 42. Increase product stock
UPDATE products SET stock_quantity = stock_quantity + 50 WHERE product_id = 1;

-- 43. Update employee status
UPDATE employees SET status = 'Inactive' WHERE employee_id = 10;

-- 44. Count employees in each warehouse
SELECT warehouse_id, COUNT(*) AS total_employees FROM employees GROUP BY warehouse_id;

-- 45. Find sales above ₹30,000
SELECT * FROM sales WHERE total_amount > 30000;

-- 46. Find suppliers from Chennai
SELECT * FROM suppliers WHERE city = 'Chennai';

-- 47. Find products with stock between 100 and 300
SELECT * FROM products WHERE stock_quantity BETWEEN 100 AND 300;

-- 48. Count sales by payment method
SELECT payment_method, COUNT(*) AS total_sales FROM sales GROUP BY payment_method;

-- 49. Find products in warehouse 5
SELECT * FROM products WHERE warehouse_id = 5;

-- 50. Display total records in all tables
SELECT (SELECT COUNT(*) FROM categories) + (SELECT COUNT(*) FROM suppliers) + (SELECT COUNT(*) FROM warehouses) + (SELECT COUNT(*) FROM products) + (SELECT COUNT(*) FROM employees) + (SELECT COUNT(*) FROM purchase_orders) + (SELECT COUNT(*) FROM purchase_order_items) + (SELECT COUNT(*) FROM sales) + (SELECT COUNT(*) FROM sale_items) + (SELECT COUNT(*) FROM stock_movements) AS total_records;
